using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Configuration;

namespace MobileBackend.Controllers
{
    [ApiController]
    [Route("api/v2/[controller]")]
    [Authorize]
    public class AssetController : ControllerBase
    {
        private readonly ILogger<AssetController> _logger;
        private readonly IAuditService _auditService;
        private readonly IConfiguration _config;
        private readonly string _baseStoragePath;

        public AssetController(
            ILogger<AssetController> logger,
            IAuditService auditService,
            IConfiguration config)
        {
            _logger = logger;
            _auditService = auditService;
            _config = config;
            _baseStoragePath = config.GetValue<string>("Storage:BasePath") ?? "/data/assets";
        }

        [HttpGet("download/{assetId}")]
        public async Task<IActionResult> DownloadAsset(string assetId)
        {
            var userId = User.FindFirst("sub")?.Value;
            await _auditService.LogAccessAsync(userId, assetId, "DOWNLOAD");

            var sanitizedId = SanitizeAssetIdentifier(assetId);
            var baseResolved = Path.GetFullPath(_baseStoragePath);
            var filePath = Path.Combine(baseResolved, sanitizedId);
            var resolvedPath = Path.GetFullPath(filePath);

            if (!resolvedPath.StartsWith(baseResolved + Path.DirectorySeparatorChar) &&
                resolvedPath != baseResolved)
            {
                _logger.LogWarning("Path traversal attempt by {User}: {Path}", userId, assetId);
                return NotFound();
            }

            if (!System.IO.File.Exists(resolvedPath))
                return NotFound();

            var stream = System.IO.File.OpenRead(resolvedPath);
            return File(stream, "application/octet-stream", Path.GetFileName(resolvedPath));
        }

        [HttpGet("list")]
        public async Task<IActionResult> ListUserAssets([FromQuery] string folder = "")
        {
            var userId = User.FindFirst("sub")?.Value;
            await _auditService.LogAccessAsync(userId, folder, "LIST");

            var userFolder = ResolveUserFolder(userId, folder);
            if (userFolder == null)
                return BadRequest("Invalid folder path");

            var entries = GetDirectoryEntries(userFolder);
            return Ok(entries);
        }

        private string ResolveUserFolder(string userId, string subFolder)
        {
            var userBase = Path.Combine(_baseStoragePath, "users", userId);
            if (string.IsNullOrWhiteSpace(subFolder))
                return userBase;

            var normalizedSub = NormalizeFolderSegment(subFolder);
            var combined = Path.Combine(userBase, normalizedSub);
            var resolved = Path.GetFullPath(combined);
            var userBaseResolved = Path.GetFullPath(userBase);

            if (!resolved.StartsWith(userBaseResolved + Path.DirectorySeparatorChar) &&
                resolved != userBaseResolved)
                return null;

            return resolved;
        }

        private string NormalizeFolderSegment(string segment)
        {
            // Remove leading/trailing separators and normalize
            segment = segment.Trim('/', '\\');
            // Collapse any encoded traversal sequences
            segment = segment.Replace("%2e", ".").Replace("%2E", ".");
            segment = segment.Replace("%2f", "/").Replace("%2F", "/");
            // Remove null bytes
            segment = segment.Replace("\0", "");
            return segment;
        }

        private object GetDirectoryEntries(string directoryPath)
        {
            if (!Directory.Exists(directoryPath))
                return new { files = Array.Empty<object>(), directories = Array.Empty<string>() };

            var files = Directory.GetFiles(directoryPath)
                .Select(f => new
                {
                    name = Path.GetFileName(f),
                    size = new FileInfo(f).Length,
                    modified = new FileInfo(f).LastWriteTimeUtc
                }).ToArray();

            var dirs = Directory.GetDirectories(directoryPath)
                .Select(d => Path.GetFileName(d)).ToArray();

            return new { files, directories = dirs };
        }

        [HttpGet("browse")]
        public async Task<IActionResult> BrowseSharedAssets([FromQuery] string path = "")
        {
            var userId = User.FindFirst("sub")?.Value;
            await _auditService.LogAccessAsync(userId, path, "BROWSE_SHARED");

            var sharedRoot = Path.Combine(_baseStoragePath, "shared");
            var targetPath = ResolveBrowsePath(sharedRoot, path);

            if (targetPath == null)
                return BadRequest("Invalid path");

            var entries = GetDirectoryEntries(targetPath);
            return Ok(entries);
        }

        private string ResolveBrowsePath(string root, string relativePath)
        {
            if (string.IsNullOrWhiteSpace(relativePath))
                return root;

            var cleaned = CleanPathInput(relativePath);
            var combined = Path.GetFullPath(Path.Combine(root, cleaned));
            var rootFull = Path.GetFullPath(root);

            // Security check: ensure we stay within root
            if (combined.StartsWith(rootFull + Path.DirectorySeparatorChar) ||
                combined == rootFull)
            {
                return combined;
            }

            return null;
        }

        private string CleanPathInput(string input)
        {
            // Decode double-encoding
            input = Uri.UnescapeDataString(input);
            // Strip dangerous characters but allow path separators
            input = new string(input.Where(c =>
                char.IsLetterOrDigit(c) || c == '/' || c == '\\' ||
                c == '-' || c == '_' || c == '.' || c == ' ').ToArray());
            return input;
        }

        private string SanitizeAssetIdentifier(string id)
        {
            return new string(id.Where(c =>
                char.IsLetterOrDigit(c) || c == '-' || c == '_' || c == '.').ToArray());
        }
    }

    public interface IAuditService
    {
        Task LogAccessAsync(string userId, string resource, string action);
    }

    public class AuditService : IAuditService
    {
        private readonly ILogger<AuditService> _logger;

        public AuditService(ILogger<AuditService> logger)
        {
            _logger = logger;
        }

        public async Task LogAccessAsync(string userId, string resource, string action)
        {
            _logger.LogInformation("AUDIT: User={User} Action={Action} Resource={Resource} Time={Time}",
                userId, action, resource, DateTime.UtcNow);
            await Task.CompletedTask;
        }
    }
}
